import * as React from "react"

import { cn } from "@/lib/utils"

type AvatarProps = Omit<React.ComponentProps<"span">, "children"> & {
  /** Who this is. It names the avatar, so say the person's name. */
  alt: string
  src?: string
  /** What shows without an image. Defaults to the first letter of alt, in italic. */
  fallback?: string
  size?: "s" | "m" | "l"
  /** The accent dot: this person is here now. */
  here?: boolean
  /** The overflow count at the end of a group ("+3"): set in the voice, not the italic. */
  count?: boolean
}

/** A person is a ring and their initial, in italic, since a name is theirs. */
function Avatar({ alt, src, fallback, size = "m", here, count, className, ...props }: AvatarProps) {
  return (
    <span
      data-slot="avatar"
      role="img"
      aria-label={here ? `${alt}, here now` : alt}
      data-size={size === "m" ? undefined : size}
      data-here={here || undefined}
      data-count={count || undefined}
      className={cn("db-avatar", className)}
      {...props}
    >
      {/* eslint-disable-next-line @next/next/no-img-element -- a registry item is framework-agnostic */}
      {src ? <img src={src} alt="" /> : (fallback ?? alt.charAt(0).toUpperCase())}
    </span>
  )
}

/** Avatars overlap, and step apart when pointed at. Its label says who the group is. */
function AvatarGroup({ className, ...props }: React.ComponentProps<"span">) {
  return <span data-slot="avatar-group" role="group" className={cn("db-avatars", className)} {...props} />
}

export { Avatar, AvatarGroup, type AvatarProps }

@layer components {
  /* ── db-avatar ── a person: a ring and their initial, in italic */
  .db-avatar {
    --s: 2.75rem; position: relative; flex: none; display: inline-grid; place-items: center; width: var(--s); height: var(--s); border-radius: 50%;
    background: var(--db-paper); box-shadow: inset 0 0 0 var(--db-hairline) var(--db-rule-strong);
    font-family: var(--db-expression); font-style: italic; font-weight: 400; font-size: calc(var(--s) * 0.46); line-height: 1; color: var(--db-ink);
  }
  .db-avatar[data-size="s"] { --s: 1.75rem; }
  .db-avatar[data-size="l"] { --s: 5rem; }
  .db-avatar > img { width: 100%; height: 100%; border-radius: 50%; object-fit: cover; filter: grayscale(1); }
  .db-avatar[data-here]::after { content: ""; position: absolute; inset-inline-end: 4%; bottom: 4%; width: max(7px, calc(var(--s) * 0.14)); aspect-ratio: 1; border-radius: 50%; background: var(--db-accent); box-shadow: 0 0 0 2px var(--db-paper); }
  .db-avatar[data-count] { font-family: var(--db-voice); font-style: normal; font-size: calc(var(--s) * 0.3); color: var(--db-graphite); }
  .db-avatars { display: inline-flex; }
  .db-avatars > .db-avatar + .db-avatar { margin-inline-start: calc(var(--s) * -0.28); transition: margin var(--db-moderato) var(--db-spiccato); }
  .db-avatars:is(:hover, [data-force~="hover"]) > .db-avatar + .db-avatar { margin-inline-start: var(--db-space-1); }
}
